// DestinyCore calls DestinyHistory{unit}.X(); LegionCore keeps cooldowns and charges on Player.
struct DestinyHistory
{
    Unit* unit;

    Player* P() const { return unit ? unit->ToPlayer() : nullptr; }
    bool HasCooldown(uint32 spellId) const { return unit && unit->HasSpellCooldown(spellId); }
    void ResetCooldown(uint32 spellId, bool update = false) { if (Player* p = P()) p->RemoveSpellCooldown(spellId, update); }
    void ModifyCooldown(uint32 spellId, int32 deltaMs) { if (Player* p = P()) p->ModifySpellCooldown(spellId, deltaMs); }
    void AddCooldown(uint32 spellId, uint32 itemId, std::chrono::milliseconds duration) { if (unit) unit->AddSpellCooldown(spellId, itemId, getPreciseTime() + duration.count() / 1000.0); }
    void RestoreSpellCharge(uint32 spellId) { if (Player* p = P()) p->ModSpellCharge(spellId, 1); }
    void ReduceSpellChargeCooldown(uint32 spellId, int32 deltaMs) { if (Player* p = P()) p->ModSpellChargeCooldown(spellId, -deltaMs); }
};

// [Death Knight] spell 45462
// Plague Strike
// spell of a proc, 0 for melee/auto attacks (they have none: dereferencing it crashed Killer Cobra on Beast Cleave hits)
static uint32 ProcSpellId(ProcEventInfo& eventInfo)
{
    SpellInfo const* spellInfo = eventInfo.GetSpellInfo();
    return spellInfo ? spellInfo->Id : 0;
}

class spell_dk_plague_strike : public SpellScriptLoader
{
public:
    spell_dk_plague_strike() : SpellScriptLoader("spell_dk_plague_strike") { }

    class spell_dk_plague_strike_SpellScript : public SpellScript
    {
        PrepareSpellScript(spell_dk_plague_strike_SpellScript);

        void HandleDummy(SpellEffIndex /*effIndex*/)
        {
            Unit* caster = GetCaster();
            if (Unit* target = GetHitUnit())
            {
                if (caster->HasAura(152281))
                    caster->CastSpell(target, 155159, true);
                else
                {
                    caster->CastSpell(target, 55078, true);
                    if (caster->HasAura(51160))
                        caster->CastSpell(target, 55095, true);
                }
            }
        }

        void Register() override
        {
            OnEffectHitTarget += SpellEffectFn(spell_dk_plague_strike_SpellScript::HandleDummy, EFFECT_1, SPELL_EFFECT_DUMMY);
        }
    };

    SpellScript* GetSpellScript() const override
    {
        return new spell_dk_plague_strike_SpellScript();
    }
};

// [Death Knight] spell 50453
// 50453 - Bloodworms Health Leech
class spell_dk_blood_gorged : public SpellScriptLoader
{
public:
    spell_dk_blood_gorged() : SpellScriptLoader("spell_dk_blood_gorged") { }

    class spell_dk_blood_gorged_AuraScript : public AuraScript
    {
        PrepareAuraScript(spell_dk_blood_gorged_AuraScript);

        bool Validate(SpellInfo const* /*spellInfo*/) override
        {
            if (!sSpellMgr->GetSpellInfo(SPELL_DK_BLOOD_GORGED_HEAL))
                return false;
            return true;
        }

        bool Load() override
        {
            _procTarget = NULL;
            return true;
        }

        bool CheckProc(ProcEventInfo& /*eventInfo*/)
        {
            _procTarget = GetTarget()->GetOwner();
            return _procTarget != nullptr;
        }

        void HandleProc(AuraEffect const* aurEff, ProcEventInfo& eventInfo)
        {
            DamageInfo* damage = eventInfo.GetDamageInfo();
            if (!damage)
                return;
            int32 heal = int32(CalculatePct(damage->GetDamage(), 150));
            GetTarget()->CastCustomSpell(SPELL_DK_BLOOD_GORGED_HEAL, SPELLVALUE_BASE_POINT0, heal, _procTarget, true, NULL, aurEff);
        }

        void Register() override
        {
            DoCheckProc += AuraCheckProcFn(spell_dk_blood_gorged_AuraScript::CheckProc);
            OnEffectProc += AuraEffectProcFn(spell_dk_blood_gorged_AuraScript::HandleProc, EFFECT_0, SPELL_AURA_PROC_TRIGGER_SPELL);
        }

    private:
        Unit* _procTarget;
    };

    AuraScript* GetAuraScript() const override
    {
        return new spell_dk_blood_gorged_AuraScript();
    }
};

